const { test } = require('node:test')
const assert = require('node:assert/strict')
const { expectedCart } = require('../oracle.cjs')

// Expected Values A19:E39 and G59:L65. Results independently evaluated with
// Python Decimal/ROUND_HALF_UP from workbook inputs, not generated by the oracle.
// These fixed reference assertions belong ONLY in offline unit tests; live carts
// must use discovered prices and the rule-driven oracle.
const references = [
	['J0', [[331, 3, '39'], [331, 3, '39']], 'plain', [4200, 0, 1536, 3110, 1848, 25694]],
	['J1', [[331, 2, '39'], [331, 1, '39'], [323, 2, '55'], [324, 1, '25']], 'plain', [1500, 0, 1896, 3839, 2281, 31716]],
	['J2', [[331, 3, '39'], [331, 2, '45'], [323, 5, '55'], [327, 3, '60'], [324, 5, '25'], [326, 3, '20']], 'plain', [11900, 0, 5824, 11794, 7007, 97425]],
	['J3', [[331, 5, '39'], [324, 3, '25']], 'vip', [4400, 3390, 1537, 3112, 1849, 25708]],
	['J4', [[331, 2, '39'], [331, 2, '39']], 'plain', [2000, 0, 1088, 2203, 1309, 18200]],
	['J5', [[331, 3, '39'], [326, 3, '20']], 'plain', [2400, 0, 1224, 2479, 1473, 20476]],
	['J7', [[331, 1, '39'], [331, 1, '39'], [324, 3, '25']], 'plain', [900, 0, 1152, 2333, 1386, 19271]],
]

for (const [journey, inputs, user, amounts] of references) {
	test(`${journey}: independently evaluated workbook total and all tax lines`, () => {
		const cart = inputs.map(([categoryId, qty, unitPrice], index) => ({
			productId: journey === 'J7' && index === 0 ? 128881 : index + 1,
			categoryIds: [categoryId], qty, unitPrice, isFreeBogoUnit: false,
		}))
		if (journey === 'J7') cart.push({ productId: 128881, categoryIds: [331], qty: 2, unitPrice: '0', isFreeBogoUnit: true })
		const actual = expectedCart(cart, user)
		assert.deepEqual([actual.bulkTotal, actual.accountTotal, actual.gross, actual.excise, actual.sales, actual.total], amounts)
	})
}
